#!/usr/bin/env python3
"""Generate context-free, deferred application messages from the English ARB."""
import argparse
import json
import subprocess
from pathlib import Path


def generate(root):
    catalog = json.loads((root / 'lib/l10n/app_en.arb').read_text())
    lines = [
        '// Generated by tool/generate_messages.py. Do not edit.',
        "import 'app_strings.dart';", '',
        '/// Retains message identity and arguments until presentation.',
        'class AppMessage {',
        '  const AppMessage._(this.key, [this.arguments = const {}]);',
        '  final String key;',
        '  final Map<String, Object> arguments;', '',
    ]
    cases = []
    for key in catalog:
        if key.startswith('@'):
            continue
        placeholders = catalog.get('@' + key, {}).get('placeholders', {})
        if placeholders:
            params = ', '.join('Object ' + p for p in placeholders)
            arguments = ', '.join("'%s': %s" % (p, p) for p in placeholders)
            lines.append(f"  static AppMessage {key}({params}) => AppMessage._('{key}', {{{arguments}}});")
            values = ', '.join("arguments['%s'] as int" % p if data.get('type') == 'int'
                               else "arguments['%s']!.toString()" % p for p, data in placeholders.items())
            cases.append(f"      '{key}' => strings.{key}({values}),")
        else:
            lines.append(f"  static const {key} = AppMessage._('{key}');")
            cases.append(f"      '{key}' => strings.{key},")
    lines += ['', '  String get text {', '    final strings = L10n.current;', '    return switch (key) {']
    lines += cases
    lines += ["      _ => throw StateError('Unknown application message: $key'),", '    };', '  }',
              '  @override', '  String toString() => text;', '}', '',
              '/// Preserves FormatException compatibility while translating on read.',
              'class LocalizedFormatException extends FormatException {',
              "  const LocalizedFormatException(this.localized) : super('');",
              '  final AppMessage localized;', '  @override', '  String get message => localized.text;', '}', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    root = Path(__file__).resolve().parent.parent
    path = root / 'lib/l10n/app_message.dart'
    content = subprocess.run(['dart', 'format', '--output=show', '--summary=none'],
                             input=generate(root), text=True, capture_output=True, check=True).stdout
    if args.check:
        if not path.exists() or path.read_text() != content:
            raise SystemExit('Run python3 tool/generate_messages.py')
    else:
        path.write_text(content)


if __name__ == '__main__':
    main()
